package com.tencent.weknora.knowledge;

import static org.junit.jupiter.api.Assertions.*;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.node.ObjectNode;
import com.tencent.weknora.security.AuthFilter;
import java.util.*;
import org.junit.jupiter.api.*;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.beans.factory.config.AutowireCapableBeanFactory;
import org.springframework.test.web.servlet.request.MockMvcRequestBuilders;

/** Real JWT/API filters, durable refresh producer, worker, model HTTP and sqlite-vec/FTS. */
@org.springframework.boot.test.context.SpringBootTest(properties={"weknora.jwt-secret=isolated-native-pipeline-trace-secret","weknora.bridge.enabled=false","weknora.knowledge.processing.enabled=true","weknora.knowledge.upload.enabled=true","weknora.tasks.enabled=true","weknora.tasks.poll-millis=3600000","weknora.retrieve-driver=sqlite","SSRF_WHITELIST=127.0.0.1","SSRF_DNS_WHITELIST_ONLY=true","NEO4J_ENABLE=false","logging.level.root=WARN","debug=false"})
@org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc
class KnowledgeUpdatePipelineHttpIntegrationTest {
 @org.springframework.test.context.DynamicPropertySource static void properties(org.springframework.test.context.DynamicPropertyRegistry p){IndexDeletePipelineHttpIntegrationTest.properties(p);}
 @Autowired AutowireCapableBeanFactory beans;
 final SummaryGenerationPipelineHttpIntegrationTest s=new SummaryGenerationPipelineHttpIntegrationTest();final ObjectMapper json=new ObjectMapper();final List<String> keys=new ArrayList<>();
 @BeforeEach void setup()throws Exception{beans.autowireBean(s);s.setup();s.f.jdbc.update("UPDATE tenant_members SET role='admin' WHERE user_id IN ('owner','caller')");s.f.jdbc.update("UPDATE kb_shares SET permission='editor',deleted_at=NULL WHERE id='trace-share'");s.f.jdbc.update("UPDATE organization_tenant_members SET role='editor' WHERE id='trace-target'");}
 @AfterEach void stop(){s.f.jdbc.execute("DROP TRIGGER IF EXISTS reject_update_refresh");for(String key:keys)s.f.jdbc.update("DELETE FROM tenant_api_keys WHERE key_hash=?",AuthFilter.hashApiKey(key));s.f.jdbc.update("UPDATE tenant_members SET role='admin' WHERE user_id IN ('owner','caller')");s.stop();}
 String prepared()throws Exception{String id=s.f.upload("A unique source explains owner permissions, metadata and summary refresh. "+UUID.randomUUID()+"");var job=s.runToSummary(id);s.f.summary.execute(job,s.f.cancellation(job));assertTrue(s.f.tasks.complete(job,json.createObjectNode()));return id;}
 JsonNode update(String doc,String credential,boolean machine,int status,String body)throws Exception{var request=MockMvcRequestBuilders.put("/api/v1/knowledge/"+doc).contentType("application/json").content(body);request.header(machine?"X-API-Key":"Authorization",machine?credential:"Bearer "+credential);var response=s.f.mvc.perform(request).andReturn().getResponse();assertEquals(status,response.getStatus(),response.getContentAsString());return json.readTree(response.getContentAsByteArray());}
 String key(String capability,boolean full,String kb)throws Exception{String key="update-key-"+UUID.randomUUID();keys.add(key);s.f.jdbc.update("INSERT INTO tenant_api_keys(tenant_id,name,key_hash,api_key,full_access,capabilities,knowledge_base_ids) VALUES(8,'Update',?,?,?,?,?)",AuthFilter.hashApiKey(key),key,full,json.writeValueAsString(List.of(capability)),json.writeValueAsString(List.of(kb)));return key;}
 List<Object> retained(String id)throws Exception{String path=s.state(id,"file_path");String source;try(var in=s.f.storage.forKnowledgeBase(8,"trace-kb").files().open(path)){source=Base64.getEncoder().encodeToString(in.readAllBytes());}return List.of(source,s.f.jdbc.queryForObject("SELECT storage_used FROM tenants WHERE id=8",Long.class),s.pending(id),s.state(id,"parse_status"),json.valueToTree(s.f.jdbc.queryForList("SELECT * FROM chunks WHERE knowledge_id=? AND chunk_type<>'summary' ORDER BY id",id)),json.valueToTree(s.f.jdbc.queryForList("SELECT e.* FROM lite_embeddings e JOIN chunks c ON c.id=e.source_id WHERE e.knowledge_id=? AND c.chunk_type<>'summary' ORDER BY e.id",id)));}
 JsonNode indexes(String id)throws Exception{var result=json.createObjectNode();result.set("rows",json.valueToTree(s.f.jdbc.queryForList("SELECT * FROM lite_embeddings WHERE knowledge_id=? ORDER BY id",id)));result.set("vectors",json.valueToTree(s.f.jdbc.execute((org.springframework.jdbc.core.ConnectionCallback<List<Map<String,Object>>>)connection->{new com.tencent.weknora.retrieval.SQLiteVectorExtension(java.nio.file.Path.of(System.getProperty("weknora.sqlite.vec.extension"))).load(connection);try(var statement=connection.prepareStatement("SELECT hex(v.embedding) AS vector,e.source_id,e.source_type FROM vec_embeddings_3 v JOIN lite_embeddings e ON e.id=v.rowid WHERE e.knowledge_id=? ORDER BY e.id")){statement.setString(1,id);try(var rs=statement.executeQuery()){var out=new ArrayList<Map<String,Object>>();while(rs.next())out.add(Map.of("vector",rs.getString(1),"source_id",rs.getString(2),"source_type",rs.getInt(3)));return out;}}})));result.set("fts",json.valueToTree(s.f.jdbc.queryForList("SELECT t.rowid,t.content FROM lite_embeddings_fts t JOIN lite_embeddings e ON e.id=t.rowid WHERE e.knowledge_id=? ORDER BY t.rowid",id)));return result;}
 @Test void creatorViewerPartialUpdateRetainsIndexesAndClearsDescriptionWithoutTask()throws Exception {
  String id=prepared();var retained=retained(id);var before=indexes(id);long jobs=s.f.jdbc.queryForObject("SELECT COUNT(*) FROM java_task_jobs",Long.class);int chats=s.chats.get(),embeddings=s.embeddings.get();s.f.jdbc.update("UPDATE tenant_members SET role='viewer' WHERE user_id='owner' AND tenant_id=8");String token=s.f.token("owner",8);
  var response=update(id,token,false,200,"{\"title\":\"中文 title\"}");assertEquals("中文 title",response.path("data").path("title").asText());assertEquals("Native objective summary 中文😀.",response.path("data").path("description").asText());
  response=update(id,token,false,200,"{\"title\":\"\",\"description\":\"\"}");assertEquals("中文 title",response.path("data").path("title").asText());assertEquals("",response.path("data").path("description").asText());assertEquals("none",response.path("data").path("summary_status").asText());
  assertEquals(before,indexes(id));assertEquals(retained,retained(id));assertEquals(jobs,s.f.jdbc.queryForObject("SELECT COUNT(*) FROM java_task_jobs",Long.class));assertEquals(chats,s.chats.get());assertEquals(embeddings,s.embeddings.get());
 }
 @Test void sharedMetadataUpdateRunsRealRefreshWithOwnerAttemptAndNewPrompt()throws Exception {
  String id=prepared();var before=retained(id);String oldSummary=s.f.jdbc.queryForObject("SELECT id FROM chunks WHERE knowledge_id=? AND chunk_type='summary'",String.class,id);int chats=s.chats.get();s.f.jdbc.update("UPDATE tenant_members SET role='contributor' WHERE user_id='caller'");
  var response=update(id,s.f.callerToken,false,200,"{\"custom_metadata\": {\"reviewer\":\"NEW METADATA OWNER\"}}");assertEquals(8,response.path("data").path("tenant_id").asLong());assertEquals("pending",response.path("data").path("summary_status").asText());assertEquals(before,retained(id));
  var refresh=s.f.claim("summary");assertTrue(refresh.payload().path("refresh").asBoolean());assertEquals(8,refresh.payload().path("tenant_id").asLong());assertEquals(1,refresh.payload().path("attempt").asLong());assertEquals(4,refresh.maxAttempts());assertEquals(1800000,refresh.timeoutMillis());assertEquals("completed",s.f.summary.execute(refresh,s.f.cancellation(refresh)).path("status").asText());assertTrue(s.f.tasks.complete(refresh,json.createObjectNode()));assertEquals(chats+1,s.chats.get());
  assertTrue(s.requests.stream().anyMatch(r->r.path("messages").toString().contains("NEW METADATA OWNER")));assertEquals("completed",s.state(id,"summary_status"));assertEquals(before,retained(id));assertEquals(oldSummary,s.f.jdbc.queryForObject("SELECT id FROM chunks WHERE knowledge_id=? AND chunk_type='summary'",String.class,id));assertEquals(s.f.count("chunks",id),s.f.count("lite_embeddings",id));assertFalse(indexes(id).path("vectors").isEmpty());
 }
 @Test void queueFailurePersistsUpdateAndApiScopePrecedesBinding()throws Exception {
  String id=prepared();var before=retained(id);var physical=indexes(id);long count=s.f.jdbc.queryForObject("SELECT COUNT(*) FROM java_task_jobs",Long.class);int chats=s.chats.get();
  String ingest=key("ingest",false,"trace-kb"),retrieve=key("retrieve",false,"trace-kb"),wrong=key("ingest",true,"other-kb");update(id,retrieve,true,403,"invalid");update(id,wrong,true,403,"invalid");update(id,s.f.foreignToken,false,403,"invalid");
  s.f.jdbc.execute("CREATE TRIGGER reject_update_refresh BEFORE INSERT ON java_task_jobs WHEN NEW.type='summary:generation' BEGIN SELECT RAISE(ABORT,'controlled refresh rejection'); END");
  var response=update(id,ingest,true,200,"{\"title\":\"Persisted title\",\"custom_metadata\":{\"reviewer\":\"retained\"}}");assertEquals("Persisted title",response.path("data").path("title").asText());assertEquals("failed",response.path("data").path("summary_status").asText());assertEquals("retained",response.path("data").path("custom_metadata").path("reviewer").asText());assertEquals(before,retained(id));assertEquals(physical,indexes(id));assertEquals(count,s.f.jdbc.queryForObject("SELECT COUNT(*) FROM java_task_jobs",Long.class));assertEquals(chats,s.chats.get());
 }
}
